"""## Data

ADL:大盤騰落指標線，即上漲家數減下跌家數
ADL指標公式如下：
ADLt=ADLt-1 + AIt - DIt


ADR:大盤漲跌比率，即上漲家數除以上漲家數加下跌家數
"""

# create ADL
def get_adl(benchmark=1,ma_range=[5,60]):
    df=data.get('etl:adj_close')
    fluctuation=df/df.shift()
    fluctuation=fluctuation.dropna(how='all')
    fluctuation=fluctuation.T

    dataset=[]
    for i in range(len(fluctuation.columns)):
      daily_stat=fluctuation.iloc[:,i].dropna()
      stats={'ups':(daily_stat>benchmark).sum(),'downs':(daily_stat<benchmark).sum()}
      dataset.append(stats)

    ad_line_df=pd.DataFrame(dataset,index=fluctuation.columns)
    ad_line_df['net']=ad_line_df['ups']-ad_line_df['downs']
    ad_line_df['ADL']=ad_line_df['net'].cumsum()
    ad_line_df['ADR']=ad_line_df['ups']/(ad_line_df['downs']+ad_line_df['ups'])
    for i in ma_range:
        s=f'ADL_MA{i}'
        s2=f'ADR_MA{i}'
        ad_line_df[s]=ad_line_df['ADL'].rolling(i).sum()/i
        ad_line_df[s2]=ad_line_df['ADR'].rolling(i).sum()/i
    return ad_line_df.dropna()


def select_date_range(df,start_date=None,end_date=None):
    if start_date:
        df=df[(df.index>=start_date)]
    if end_date:
        df=df[(df.index<=end_date)]
    return df

# 分出金叉與死叉區間
def split_values_cross(df,col_1,col_2):
    # split data into chunks where values cross each other
    df['label'] = np.where(df[col_1]>df[col_2], 1, 0)
    df['group'] = df['label'].ne(df['label'].shift()).cumsum()
    original_df=df.copy()
    df = df.groupby('group')
    split_dfs = [data for name, data in df]
    return original_df,split_dfs

"""## Static

### split_values_cross
"""

adl=get_adl()
adl_select=adl[['ADL_MA5','ADL_MA60']].copy()
original_df,split_dfs=split_values_cross(adl_select,'ADL_MA5','ADL_MA60')

"""### calculate return"""

close=data.get('etl:adj_close')
close_index=list(close.index)


def adl_signal_statistic(area):
    min_date=area.index.min()
    max_date=area.index.max()

    if len(area)>2:
        entry_index=close_index.index(min_date)+1
        exit_index=close_index.index(max_date)+2
    else:
        entry_index=close_index.index(min_date)
        exit_index=close_index.index(max_date)

    entry_data=close.iloc[entry_index].dropna()
    try:
        exit_data=close.iloc[exit_index].dropna()
    except:
        # handle last period
        exit_index=exit_index-2
        exit_data=close.iloc[exit_index].dropna()
    return_value=(exit_data*(1-0.004)-entry_data*0.001)/entry_data-1
    return_value=return_value[return_value!=np.inf]
    win=return_value[return_value>0]
    win_ratio=len(win)/len(return_value)
    result={'entry_date':close_index[entry_index],'exit_date':close_index[exit_index],'period':exit_index-entry_index,'win_ratio':win_ratio,'return_avg':return_value.mean()}
    return result


# backtest include fee & tax
stat_df=pd.DataFrame([adl_signal_statistic(area) for area in split_dfs])
stat_df['cross']=['long' if (num % 2) ==0 else 'short' for num in stat_df.index ]
stat_df['entry_date']=stat_df['entry_date'].dt.strftime('%Y-%m-%d')
stat_df['exit_date']=stat_df['exit_date'].dt.strftime('%Y-%m-%d')
stat_df['0050_entry']=close.loc[list(stat_df['entry_date']),'0050'].values
stat_df['0050_exit']=close.loc[stat_df['exit_date'].values,'0050'].values
stat_df['0050_return']= (stat_df['0050_exit']*(1-0.004)-stat_df['0050_entry']*0.001)/stat_df['0050_entry']-1
stat_df['0050_return_cumprod']=(stat_df['0050_return']+1).cumprod()
stat_df['adl_0050_strategy']=[return_avg+1 if cross=='long' else etf_return+1 for return_avg,cross,etf_return in zip(stat_df['return_avg'],stat_df['cross'],stat_df['0050_return'])]
stat_df['adl_0050_strategy']=stat_df['adl_0050_strategy'].cumprod()
stat_df['adl_clearance_strategy']=[return_avg+1 if cross=='long' else 1 for return_avg,cross,etf_return in zip(stat_df['return_avg'],stat_df['cross'],stat_df['0050_return'])]
stat_df['adl_clearance_strategy']=stat_df['adl_clearance_strategy'].cumprod()
stat_df['adl_short_strategy']=[etf_return+1 if cross=='long' else return_avg+1 for return_avg,cross,etf_return in zip(stat_df['return_avg'],stat_df['cross'],stat_df['0050_return'])]
stat_df['adl_short_strategy']=stat_df['adl_short_strategy'].cumprod()
stat_df['market_return_avg']=(stat_df['return_avg']+1).cumprod()
stat_df

mean_stat=stat_df.groupby(['cross'])[['period','win_ratio','return_avg']].mean()
mean_stat.columns=['mean_'+c for c in mean_stat.columns]
mean_stat

